from typing import List
from collections import Counter
import bisect

def gcdValues(A: List[int], queries: List[int]) -> List[int]:
    MX = 50001
    divisors = [[] for _ in range(MX)]
    countD = {}
    countG = {}
    ans = []
    M = max(A)

    for x in range(1, MX):
        for y in range(x, MX, x):
            divisors[y].append(x)

    countA = {}
    for num in A:
        countA[num] = countA.get(num, 0) + 1

    for x, freq in countA.items():
        for d in divisors[x]:
            countD[d] = countD.get(d, 0) + freq

    countG = {}
    for g in range(M, 0, -1):
        c = countD.get(g, 0)
        if c <= 1:
            countG[g] = c * (c - 1) // 2
        for x in range(2 * g, M + 1, g):
            countG[g] = countG.get(g, 0) - countG.get(x, 0)

    glist = list(reversed(sorted(countG.keys())))
    vlist = list(reversed(countG.values()))

    Pvlist = []
    acc = 0
    for v in vlist:
        acc += v
        Pvlist.append(acc)

    for q in queries:
        i = bisect.bisect_left(Pvlist, q + 1)
        ans.append(glist[i])

    return ans
